<?php

namespace Modules\Payroll\Services;

use Modules\Payroll\Repositories\SalaryStructureRepository;

class SalaryStructureService
{
    public function __construct(private SalaryStructureRepository $structures) {}
    public function list(bool $all=false): array { return ['success'=>true,'structures'=>$this->structures->all(!$all)]; }
    public function show(string $id): array { $structure=$this->structures->find($id); return $structure ? ['success'=>true,'structure'=>$structure,'assignments'=>$this->structures->assignments($id)] : $this->notFound(); }
    public function create(array $data): array { $data=$this->normalize($data);$error=$this->validate($data); if($error)return $error; if($this->structures->findByCode($data['structure_code']))return ['success'=>false,'message'=>'A salary structure with this code already exists.','status'=>409]; return ['success'=>true,'message'=>'Salary structure created.','structure'=>$this->structures->create($data)]; }
    public function update(string $id,array $data): array { $current=$this->structures->find($id);if(!$current)return $this->notFound();$data=$this->normalize($data);$merged=array_merge($current,$data);$error=$this->validate($merged);if($error)return $error;if(($data['structure_code']??$current['structure_code'])!==$current['structure_code']&&$this->structures->findByCode($data['structure_code']))return ['success'=>false,'message'=>'A salary structure with this code already exists.','status'=>409];return ['success'=>true,'message'=>'Salary structure updated.','structure'=>$this->structures->update($id,$data)]; }
    public function delete(string $id): array { $structure=$this->structures->find($id);if(!$structure)return $this->notFound();$usage=$this->structures->usage($id);if($usage['assignments']>0||$usage['payrolls']>0)return ['success'=>false,'message'=>'A salary structure with assignments or payroll history cannot be deleted. Mark it inactive instead.','status'=>409];$this->structures->delete($id);return ['success'=>true,'message'=>'Salary structure deleted.']; }
    public function assign(string $id,array $data): array { $structure=$this->structures->find($id);if(!$structure)return $this->notFound();if($structure['status']!=='Active')return ['success'=>false,'message'=>'An inactive salary structure cannot be assigned.','status'=>409];$employees=$data['employee_ids']??[];if(!is_array($employees)||!$employees)return ['success'=>false,'message'=>'At least one employee_id is required.','status'=>422];$date=(string)($data['effective_from']??date('Y-m-d'));if(!$this->date($date))return ['success'=>false,'message'=>'effective_from must be a valid date.','status'=>422];$employees=array_values(array_unique(array_filter(array_map(static fn($id):string=>trim((string)$id),$employees))));if(!$employees)return ['success'=>false,'message'=>'At least one employee_id is required.','status'=>422];$invalid=$this->missingEmployees($employees);if($invalid)return ['success'=>false,'message'=>'One or more employees do not exist.','invalid_employee_ids'=>$invalid,'status'=>422];$db=\Core\Database::connection();$db->beginTransaction();try{$assignments=[];foreach($employees as $employeeId)$assignments[]=$this->structures->assign($id,$employeeId,$date);$db->commit();return ['success'=>true,'message'=>'Salary structure assigned.','assignments'=>$assignments];}catch(\DomainException $e){if($db->inTransaction())$db->rollBack();return ['success'=>false,'message'=>$e->getMessage(),'status'=>409];}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;} }
    private function validate(array $d): ?array { if(trim((string)($d['structure_name']??''))===''||trim((string)($d['structure_code']??''))==='')return ['success'=>false,'message'=>'structure_name and structure_code are required.','status'=>422];if(isset($d['status'])&&!in_array($d['status'],['Active','Inactive'],true))return ['success'=>false,'message'=>'status must be Active or Inactive.','status'=>422];foreach(['basic_percentage','hra_percentage'] as $field)if(!isset($d[$field])||!is_numeric($d[$field])||(float)$d[$field]<0||(float)$d[$field]>100)return ['success'=>false,'message'=>"$field must be between 0 and 100.",'status'=>422];if((float)$d['basic_percentage']+(float)$d['hra_percentage']>100)return ['success'=>false,'message'=>'Basic and HRA percentages cannot exceed 100% together.','status'=>422];foreach(['special_allowance','medical_allowance','conveyance_allowance','bonus_value'] as $field)if(!isset($d[$field])||!is_numeric($d[$field])||(float)$d[$field]<0)return ['success'=>false,'message'=>"$field must be a non-negative amount.",'status'=>422];$bonusType=trim((string)($d['bonus_type']??''));$bonusFrequency=trim((string)($d['bonus_frequency']??''));if(($bonusType==='')!==($bonusFrequency===''))return ['success'=>false,'message'=>'bonus_type and bonus_frequency must be provided together.','status'=>422];if($bonusType!==''&&!in_array(strtolower($bonusType),['fixed','percentage'],true))return ['success'=>false,'message'=>'bonus_type must be Fixed or Percentage.','status'=>422];if($bonusFrequency!==''&&!in_array(strtolower($bonusFrequency),['monthly','quarterly','half-yearly','yearly','annual'],true))return ['success'=>false,'message'=>'bonus_frequency must be Monthly, Quarterly, Half-Yearly, Yearly, or Annual.','status'=>422];if(strtolower($bonusType)==='percentage'&&(float)$d['bonus_value']>100)return ['success'=>false,'message'=>'bonus_value cannot exceed 100 for a percentage bonus.','status'=>422];return null; }
    private function normalize(array $d): array { if(isset($d['structure_code']))$d['structure_code']=strtoupper(trim((string)$d['structure_code']));return $d; }
    private function date(string $value): bool { $d=\DateTime::createFromFormat('Y-m-d',$value);return $d&&$d->format('Y-m-d')===$value; }
    private function missingEmployees(array $ids): array { if(!$ids)return []; $sql='SELECT employee_id FROM employees WHERE employee_id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$stmt=\Core\Database::connection()->prepare($sql);$stmt->execute($ids);return array_values(array_diff($ids,array_column($stmt->fetchAll(),'employee_id'))); }
    private function notFound(): array { return ['success'=>false,'message'=>'Salary structure not found.','status'=>404]; }
}
